//! The `/api/v1/requests` bodies (guides/api.md#responses). Generated by `cargo offrails generate api requests`.
//! Frozen once clients use them: add fields freely, rename or remove only in /api/v2.

use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

use crate::controllers::api::PageInfo;
use crate::models::request::{self, RequestParams};

/// One request, as the API shows it (never the entity: new columns don't leak).
#[derive(Debug, Clone, Serialize, ToSchema)]
pub struct RequestJson {
    pub id: i64,
    pub agent_id: i64,
    pub title: String,
    pub description: String,
    pub category: String,
    pub location: String,
    pub budget_cents: i64,
    pub status: request::RequestStatus,
    pub created_at: chrono::DateTime<chrono::Utc>,
    pub updated_at: chrono::DateTime<chrono::Utc>,
}

impl From<&request::Model> for RequestJson {
    fn from(r: &request::Model) -> Self {
        Self {
            id: r.id,
            agent_id: r.agent_id,
            title: r.title.clone(),
            description: r.description.clone(),
            category: r.category.clone(),
            location: r.location.clone(),
            budget_cents: r.budget_cents,
            status: r.status,
            created_at: r.created_at,
            updated_at: r.updated_at,
        }
    }
}

/// `{"data": {…}}`
#[derive(Debug, Clone, Serialize, ToSchema)]
pub struct RequestBody {
    pub data: RequestJson,
}

/// `{"data": [...], "page": {…}}`
#[derive(Debug, Clone, Serialize, ToSchema)]
pub struct RequestsPage {
    pub data: Vec<RequestJson>,
    pub page: PageInfo,
}

/// The JSON a client sends. Absent fields keep their value on update. No owner: it's the token's.
#[derive(Debug, Clone, Default, Deserialize, ToSchema)]
pub struct RequestInput {
    #[serde(default)]
    pub agent_id: Option<i64>,
    #[serde(default)]
    pub title: Option<String>,
    #[serde(default)]
    pub description: Option<String>,
    #[serde(default)]
    pub category: Option<String>,
    #[serde(default)]
    pub location: Option<String>,
    /// An amount: "12.30".
    #[serde(default)]
    pub budget: Option<String>,
}

impl RequestInput {
    /// Onto `base` (empty on create, the saved values on update), then `validate()` as the form does.
    pub fn onto(self, mut p: RequestParams) -> RequestParams {
        if let Some(v) = self.agent_id {
            p.agent_id = v.to_string();
        }
        if let Some(v) = self.title {
            p.title = v;
        }
        if let Some(v) = self.description {
            p.description = v;
        }
        if let Some(v) = self.category {
            p.category = v;
        }
        if let Some(v) = self.location {
            p.location = v;
        }
        if let Some(v) = self.budget {
            p.budget = v;
        }
        p
    }
}
